export function validateBackgroundFailureStage(value: unknown, path: string, contract: string): void {
  if (!(["SCHEDULE_SCHEDULER", "FLEET_RUN_SUPERVISOR"] as unknown[]).includes(value)) fail(contract, path, "was not an allowed enum value");
  if (typeof value !== "string") fail(contract, path, "expected string");
}

export function validateBlockedOperationOutcome(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "state")) fail(contract, `${path}.state`, "missing required property");
  if (!Object.hasOwn(record, "reason_code")) fail(contract, `${path}.reason_code`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "reason_code": {
          validateReference("ReasonCode", validateReasonCode, item, `${path}.reason_code`, contract, refStack);
          break;
        }
        case "returncode": {
          if (item !== 0) fail(contract, `${path}.returncode`, "did not match required constant");
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.returncode`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.returncode`, "expected integer");
          break;
        }
        case "state": {
          if (item !== "blocked") fail(contract, `${path}.state`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.state`, "expected string");
          break;
        }
        case "verdict": {
          if (item !== "MANUAL_ACTION_REQUIRED") fail(contract, `${path}.verdict`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.verdict`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateBlockedSharedPlanRepositoryPreview(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "repository")) fail(contract, `${path}.repository`, "missing required property");
  if (!Object.hasOwn(record, "repository_instance_id")) fail(contract, `${path}.repository_instance_id`, "missing required property");
  if (!Object.hasOwn(record, "reason")) fail(contract, `${path}.reason`, "missing required property");
  if (!Object.hasOwn(record, "diagnostic")) fail(contract, `${path}.diagnostic`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "diagnostic": {
          validateReference("OperatorWhyNotDiagnostic", validateOperatorWhyNotDiagnostic, item, `${path}.diagnostic`, contract, refStack);
          break;
        }
        case "reason": {
          if (typeof item !== "string") fail(contract, `${path}.reason`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.reason`, "must contain at least 1 characters");
          if ((item as string).length > 1000) fail(contract, `${path}.reason`, "must contain at most 1000 characters");
          break;
        }
        case "repository": {
          validateReference("RepositoryIdentity", validateRepositoryIdentity, item, `${path}.repository`, contract, refStack);
          break;
        }
        case "repository_instance_id": {
          if (typeof item !== "string") fail(contract, `${path}.repository_instance_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.repository_instance_id`, "must contain at least 1 characters");
          break;
        }
        case "state": {
          if (item !== "BLOCKED") fail(contract, `${path}.state`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.state`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
